class LmdbRepositoryValueExposureTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:repository-exposure:subject");
	private static final IRI PREDICATE = VF.createIRI("urn:repository-exposure:predicate");
	private static final IRI CONTEXT = VF.createIRI("urn:repository-exposure:context");
	private static final IRI DATATYPE = VF.createIRI("urn:repository-exposure:datatype");
	private static final String SELECT = "SELECT ?value WHERE { ?s <" + PREDICATE + "> ?value }";
	private static final String CONSTRUCT = "CONSTRUCT { ?s <" + PREDICATE + "> ?value } WHERE { ?s <"
			+ PREDICATE + "> ?value }";

	private enum Route {
		STATEMENTS,
		CONTEXTS,
		TUPLE,
		GRAPH,
		NAMESPACES,
		EXPORT,
		TUPLE_HANDLER,
		GRAPH_HANDLER
	}

	private enum RowReuse {
		BINDINGS,
		STATEMENTS
	}

	@Test
	void rawSailStatementsRemainLazy(@TempDir File directory) {
		seed(directory, 1);
		LmdbStore store = newStore(directory);
		store.init();
		try (NotifyingSailConnection connection = store.getConnection();
				CloseableIteration<? extends Statement> statements = connection.getStatements(null, null, null,
						false)) {
			assertTrue(statements.hasNext());
			assertLazy(statements.next().getObject());
			assertFalse(statements.hasNext());
		} finally {
			store.shutDown();
		}
	}

	@ParameterizedTest
	@EnumSource(Route.class)
	void repositoryRoutesExposeReadyValuesThroughWrapperStack(Route route, @TempDir File directory) {
		seed(directory, 1);
		ProbeSail probe = new ProbeSail(newStore(directory), -1);
		SailRepository repository = new SailRepository(probe);
		List<Value> retained = new ArrayList<>();
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			switch (route) {
			case STATEMENTS:
				try (RepositoryResult<Statement> statements = connection.getStatements(null, null, null, false)) {
					while (statements.hasNext()) {
						retainReadyStatement(statements.next(), retained);
					}
				}
				break;
			case CONTEXTS:
				try (RepositoryResult<Resource> contexts = connection.getContextIDs()) {
					while (contexts.hasNext()) {
						Value context = contexts.next();
						assertDeepReady(context);
						retained.add(context);
					}
				}
				break;
			case TUPLE:
				try (TupleQueryResult result = connection.prepareTupleQuery(SELECT).evaluate()) {
					while (result.hasNext()) {
						retainReady(result.next().getValue("value"), retained);
					}
				}
				break;
			case GRAPH:
				try (GraphQueryResult result = connection.prepareGraphQuery(CONSTRUCT).evaluate()) {
					while (result.hasNext()) {
						retainReadyStatement(result.next(), retained);
					}
				}
				break;
			case NAMESPACES:
				try (RepositoryResult<Namespace> namespaces = connection.getNamespaces()) {
					assertTrue(namespaces.hasNext());
					assertEquals("urn:repository-exposure:", namespaces.next().getName());
					assertFalse(namespaces.hasNext());
				}
				break;
			case EXPORT:
				connection.export(new AbstractRDFHandler() {
					@Override
					public void handleStatement(Statement statement) {
						retainReadyStatement(statement, retained);
					}
				});
				break;
			case TUPLE_HANDLER:
				connection.prepareTupleQuery(SELECT).evaluate(new AbstractTupleQueryResultHandler() {
					@Override
					public void handleSolution(BindingSet bindings) {
						retainReady(bindings.getValue("value"), retained);
					}
				});
				break;
			case GRAPH_HANDLER:
				connection.prepareGraphQuery(CONSTRUCT).evaluate(new AbstractRDFHandler() {
					@Override
					public void handleStatement(Statement statement) {
						retainReadyStatement(statement, retained);
					}
				});
				break;
			}
			assertTrue(probe.rows.get() > 0, "The wrapper stack must participate in outward retrieval");
		} finally {
			repository.shutDown();
		}
		retained.forEach(LmdbRepositoryValueExposureTest::assertDeepReady);
		retained.forEach(Value::stringValue);
	}

	@Test
	void repositoryBatchPreservesExactSourceOrderAndRows(@TempDir File directory) {
		seed(directory, 257);
		ProbeSail probe = new ProbeSail(newStore(directory), -1);
		SailRepository repository = new SailRepository(probe);
		repository.init();
		List<Long> outwardIds = new ArrayList<>();
		try (RepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(SELECT).evaluate()) {
			while (result.hasNext()) {
				Value value = result.next().getValue("value");
				assertDeepReady(value);
				outwardIds.add(((LmdbValue) value).getInternalID());
			}
			assertEquals(257, outwardIds.size());
			assertEquals(probe.sourceIds, outwardIds, "Dictionary-locality work must preserve the exact row sequence");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void repositoryBatchDeliversPrefixBeforeSourceFailure(@TempDir File directory) {
		seed(directory, 3);
		ProbeSail probe = new ProbeSail(newStore(directory), 2);
		SailRepository repository = new SailRepository(probe);
		repository.init();
		try (RepositoryConnection connection = repository.getConnection();
				RepositoryResult<Statement> statements = connection.getStatements(null, null, null, false)) {
			retainReadyStatement(statements.next(), new ArrayList<>());
			retainReadyStatement(statements.next(), new ArrayList<>());
			RepositoryException failure = assertThrows(RepositoryException.class, statements::next);
			assertSame(probe.failure, failure.getCause());
			assertEquals(1, probe.closed.get(), "An outward batch failure must close its source exactly once");
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@EnumSource(RowReuse.class)
	void repositoryBatchSnapshotsReusedSourceContainers(RowReuse reuse, @TempDir File directory) {
		seed(directory, 17);
		ProbeSail probe = new ProbeSail(newStore(directory), -1, reuse);
		SailRepository repository = new SailRepository(probe);
		repository.init();
		List<Long> retainedIds = new ArrayList<>();
		try (RepositoryConnection connection = repository.getConnection()) {
			if (reuse == RowReuse.BINDINGS) {
				List<BindingSet> retained = new ArrayList<>();
				try (TupleQueryResult result = connection.prepareTupleQuery(SELECT).evaluate()) {
					while (result.hasNext()) {
						BindingSet row = result.next();
						assertDeepReady(row.getValue("value"));
						retained.add(row);
					}
				}
				retained.forEach(row -> retainedIds.add(((LmdbValue) row.getValue("value")).getInternalID()));
			} else {
				List<Statement> retained = new ArrayList<>();
				try (RepositoryResult<Statement> result = connection.getStatements(null, null, null, false)) {
					while (result.hasNext()) {
						Statement row = result.next();
						assertDeepReady(row.getObject());
						retained.add(row);
					}
				}
				retained.forEach(row -> retainedIds.add(((LmdbValue) row.getObject()).getInternalID()));
			}
			assertEquals(17, retainedIds.size());
			assertEquals(probe.sourceIds, retainedIds,
					"A source may reuse its row container; buffered outward rows must retain their own values");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void functionCallbackStaysLazyUntilRepositoryResult(@TempDir File directory) {
		seed(directory, 1);
		String functionIRI = "urn:repository-exposure:function:" + UUID.randomUUID();
		AtomicInteger callbacks = new AtomicInteger();
		Function function = new Function() {
			@Override
			public String getURI() {
				return functionIRI;
			}

			@Override
			public boolean mustReturnDifferentResult() {
				return true;
			}

			@Override
			public Value evaluate(ValueFactory factory, Value... args) {
				throw new AssertionError("Function must receive a TripleSource");
			}

			@Override
			public Value evaluate(TripleSource source, Value... args) {
				assertLazy(args[0]);
				callbacks.incrementAndGet();
				return args[0];
			}
		};
		FunctionRegistry.getInstance().add(function);
		SailRepository repository = new SailRepository(newStore(directory));
		repository.init();
		try (RepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery("SELECT ?result WHERE { ?s <" + PREDICATE
						+ "> ?value . BIND(<" + functionIRI + ">(?value) AS ?result) }").evaluate()) {
			assertTrue(result.hasNext());
			assertDeepReady(result.next().getValue("result"));
			assertFalse(result.hasNext());
			assertEquals(1, callbacks.get());
		} finally {
			FunctionRegistry.getInstance().remove(function);
			repository.shutDown();
		}
	}

	private static LmdbStore newStore(File directory) {
		return new LmdbStore(directory, new LmdbStoreConfig().setInlineLiterals(false));
	}

	private static void seed(File directory, int rows) {
		SailRepository repository = new SailRepository(newStore(directory));
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			connection.setNamespace("ex", "urn:repository-exposure:");
			for (int row = 0; row < rows; row++) {
				Literal literal = VF.createLiteral("nested outward value " + row, DATATYPE);
				TripleTerm inner = VF.createTripleTerm(SUBJECT, PREDICATE, literal);
				TripleTerm outer = VF.createTripleTerm(SUBJECT, PREDICATE, inner);
				connection.add(SUBJECT, PREDICATE, outer, CONTEXT);
			}
			connection.commit();
		} finally {
			repository.shutDown();
		}
	}

	private static void assertLazy(Value value) {
		LmdbValue lmdb = assertInstanceOf(LmdbValue.class, value);
		assertInstanceOf(ValueStoreRevision.Lazy.class, lmdb.getValueStoreRevision(),
				"Sail retrieval and intermediate callbacks must preserve deferred payloads");
	}

	private static void retainReady(Value value, List<Value> retained) {
		assertDeepReady(value);
		retained.add(value);
	}

	private static void retainReadyStatement(Statement statement, List<Value> retained) {
		retainReady(statement.getSubject(), retained);
		retainReady(statement.getPredicate(), retained);
		retainReady(statement.getObject(), retained);
		if (statement.getContext() != null) {
			retainReady(statement.getContext(), retained);
		}
	}

	private static void assertDeepReady(Value value) {
		if (value instanceof LmdbValue lmdb) {
			assertInstanceOf(ValueStoreRevision.Default.class, lmdb.getValueStoreRevision(),
					"Repository callers must receive recursively ready values before any lexical getter");
		}
		if (value instanceof TripleTerm triple) {
			assertDeepReady(triple.getSubject());
			assertDeepReady(triple.getPredicate());
			assertDeepReady(triple.getObject());
		} else if (value instanceof Literal literal) {
			assertDeepReady(literal.getDatatype());
		}
	}

	private static final class ProbeSail extends NotifyingSailWrapper {
		private final AtomicInteger rows = new AtomicInteger();
		private final AtomicInteger closed = new AtomicInteger();
		private final List<Long> sourceIds = new ArrayList<>();
		private final SailException failure = new SailException("injected source failure after prefix");
		private final int failAfter;
		private final RowReuse reuse;

		private ProbeSail(LmdbStore store, int failAfter) {
			this(store, failAfter, null);
		}

		private ProbeSail(LmdbStore store, int failAfter, RowReuse reuse) {
			super(store);
			this.failAfter = failAfter;
			this.reuse = reuse;
		}

		@Override
		public NotifyingSailConnection getConnection() {
			return new NotifyingSailConnectionWrapper(new NotifyingSailConnectionWrapper(super.getConnection()) {
				@Override
				public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
						boolean includeInferred, Resource... contexts) {
					CloseableIteration<? extends Statement> source = super.getStatements(subj, pred, obj,
							includeInferred, contexts);
					if (reuse == RowReuse.STATEMENTS) {
						ReusedStatement row = new ReusedStatement();
						source = new ConvertingIteration<Statement, Statement>(source) {
							@Override
							protected Statement convert(Statement statement) {
								row.current = statement;
								return row;
							}
						};
					}
					return observe(source, Statement::getObject);
				}

				@Override
				public CloseableIteration<? extends Resource> getContextIDs() {
					return observe(super.getContextIDs(), value -> value);
				}

				@Override
				public CloseableIteration<? extends BindingSet> evaluate(TupleExpr expression, Dataset dataset,
						BindingSet bindings, boolean includeInferred) {
					CloseableIteration<? extends BindingSet> source = super.evaluate(expression, dataset, bindings,
							includeInferred);
					if (reuse == RowReuse.BINDINGS) {
						MapBindingSet row = new MapBindingSet();
						source = new ConvertingIteration<BindingSet, BindingSet>(source) {
							@Override
							protected BindingSet convert(BindingSet bindings) {
								row.clear();
								bindings.forEach(binding -> row.addBinding(binding.getName(), binding.getValue()));
								return row;
							}
						};
					}
					return observe(source, result -> {
						Value value = result.getValue("value");
						return value == null ? result.getValue("object") : value;
					});
				}

				@Override
				public CloseableIteration<? extends Namespace> getNamespaces() {
					return observe(super.getNamespaces(), result -> null);
				}
			}) {
			};
		}

		private <T> CloseableIteration<T> observe(CloseableIteration<? extends T> source,
				ValueRoot<T> root) {
			return new IterationWrapper<>(source) {
				@Override
				public T next() {
					if (failAfter >= 0 && rows.get() == failAfter) {
						throw failure;
					}
					T result = super.next();
					Value value = root.get(result);
					if (value != null) {
						assertLazy(value);
						sourceIds.add(((LmdbValue) value).getInternalID());
					}
					rows.incrementAndGet();
					return result;
				}

				@Override
				protected void handleClose() {
					closed.incrementAndGet();
					super.handleClose();
				}
			};
		}
	}

	@FunctionalInterface
	private interface ValueRoot<T> {
		Value get(T row);
	}

	private static final class ReusedStatement extends AbstractStatement {
		private static final long serialVersionUID = 1L;
		private Statement current;

		@Override
		public Resource getSubject() {
			return current.getSubject();
		}

		@Override
		public IRI getPredicate() {
			return current.getPredicate();
		}

		@Override
		public Value getObject() {
			return current.getObject();
		}

		@Override
		public Resource getContext() {
			return current.getContext();
		}
	}
}
